(function(){
  'use strict';
  const gm=Boolean(document.getElementById('saveCampaignBackup'));
  const pages={
    campaign:[
      [gm?'Campaign — Build and Explore Your Universe':'Campaign — Explore Your Universe',gm?
        `<p>The <strong class="help-check">Campaign</strong> tab is your shared universe: sectors, star systems, planets, and regional maps. Build locations before a session or develop them as the party explores.</p><h3>Find your place</h3><p>The four-part location bar reads <strong>Sector → Star System → Planet → Region</strong>. Click an available section to inspect that view. The glowing section is the view you are looking at; the tiny red pin marks the party’s location. Empty sections have no current location.</p><p class="help-reminder"><strong>Browsing a map does not move the party or its ship.</strong> Use the travel or relocation controls for that.</p><p>Drag empty space to pan, use the wheel or <strong>+ / −</strong> to zoom, and use <strong>Fit Map</strong> to frame the map. <strong class="help-check">Enlarge Map</strong> fills the workspace; the yellow <strong>Return to Campaign</strong> restores the normal view.</p><p>Use the <strong>envelope beside Help</strong> for private messages, results, and travel requests. The following pages explain creation, exploration, travel, and location resources.</p>`:
        `<p>The <strong class="help-check">Campaign</strong> tab shows the maps and destinations your GM has made available. Use it to read location information, follow your party, and plan travel.</p><h3>Read the location bar</h3><p>The four sections are <strong>Sector → Star System → Planet → Region</strong>. The glowing section identifies your current map view. The tiny red pin identifies the party’s location. Empty or disabled sections are not currently available.</p><p class="help-reminder"><strong>Changing your view does not move your character, party, or ship.</strong> Some views become available only after travel or a GM change.</p><p>Drag empty space to pan, scroll or press <strong>+ / −</strong> to zoom, and use <strong>Fit Map</strong> to frame the map. <strong class="help-check">Enlarge Map</strong> fills the workspace; <strong>Return to Campaign</strong> restores the normal view.</p><p>The <strong>envelope beside Help</strong> opens Private Notes. Read GM messages, travel decisions, rewards, and other notices there, or send a private message to your GM.</p>`,gm?'campaign-gm-overview':'campaign-pc-overview','Overview'],
      [gm?'Galaxy Maps — Create, Inspect, and Navigate':'Galaxy Maps — Explore Known Stars',gm?
        `<h3>Create and save maps</h3><p>Open <strong class="help-check">Map options</strong> for <strong>New Galaxy Map</strong>, <strong>Save Galaxy Map</strong>, <strong>Load Galaxy Map</strong>, and <strong>PC Map Visibility</strong>. Loading a galaxy file adds a new map. Use the map dropdown to switch maps.</p><h3>Place and edit stars</h3><p>Press <strong>Add Star</strong>, then click an empty hex and name the star. Select <strong class="help-check">Inspect Stars</strong> and click a star to read its details. <strong>Reposition Stars</strong> lets you drag stars; <strong>Edit Stars</strong> opens editing when you click one. <strong>Move Ships</strong> directly relocates the selected ship. <strong>Pan Map</strong> moves the view. The highlighted mode tells you which action is active. <strong>Edit Details</strong> changes its name, description, and visibility; <strong>Edit Solar System</strong> edits the objects around it. <strong>Star directory</strong> helps you find a star by name.</p><h3>Scale and visibility</h3><p>New maps start at one <strong class="help-reminder">parsec</strong> per hex, displayed as <strong>3.26 light-years</strong>. Existing maps retain their saved scale. <strong>Change Distances</strong> changes travel distance and fuel use, not the map’s size on screen; finish current journeys on that map first.</p><p><strong class="help-check">PC Map Visibility</strong> sets the player starting view and available map levels. Star and planet visibility also affect what players can inspect. Choose a ship and open <strong>Ship &amp; travel</strong> to place it or review a journey.</p>`:
        `<p>The Galaxy Map shows the stars your GM has made available. Its dropdown selects an available map; <strong class="help-check">Star directory</strong> lists its visible stars.</p><h3>Inspect a destination</h3><p>Click a star to read its public description and listed planets. Selecting a star only inspects it. To travel, select your ship, open <strong>Ship &amp; travel</strong>, and use <strong>Review Journey</strong>. Page 5 explains fuel and departure.</p><p><strong>Find Ship</strong> centers the chart on your selected ship. <strong>Enter Star System</strong> opens the system at your ship’s current star when available.</p><h3>Read the distance scale</h3><p>The displayed scale tells you how many light-years each hex represents. One <strong class="help-reminder">parsec</strong> is displayed as <strong>3.26 light-years</strong>, but the GM can give a map a different scale.</p><p class="help-reminder">An unavailable map level or destination may reflect GM visibility settings or the party’s current location. Returning to the Galaxy Map is not a way to leave a planet.</p>`,gm?'campaign-star-details':null,'Galaxy Maps'],
      ['Star Systems — Planets and Orbits',gm?
        `<h3>Open a system</h3><p>Select a star on the Galaxy Map, then choose <strong class="help-check">View [star name] System</strong>. This lets you inspect and edit it without moving the party. <strong>Enter Star System</strong> is also available for a ship at its current star.</p><h3>Edit planets</h3><p><strong>Edit Solar System</strong> opens the system layout editor. When placing a planet, choose <strong class="help-check">Planet (Large)</strong> (120 × 40), <strong class="help-check">Planet (Small)</strong> (60 × 20), or <strong class="help-check">Moon</strong> (30 × 10). Moons start with Moon artwork and terrain; appearance can be changed later. The system starts in <strong class="help-check">Edit Planets</strong> mode. Click a planet to edit its size, name, public description, and appearance. The same editor is available in <strong>Browse Planets</strong> and on the surface. To move a planet, select <strong class="help-check">Reposition Planets</strong> and drag its icon. The highlighted button always identifies the active action. Authored hexes and regions are preserved when appearance changes. Resizing first trims unused surroundings and compacts unused gaps to retain cities and regions. If their placement cannot fit, a warning lets you cancel or confirm. A recovery snapshot keeps the original map in the campaign save.</p><p><strong>Browse Planets</strong> lists the system’s planets. Use <strong>View Surface · [planet]</strong> to inspect a surface, or <strong>Preview Surface</strong> for a small map preview.</p><h3>Move a ship</h3><p>Select <strong class="help-check">Plot Travel</strong>, choose a ship, click a destination hex, then <strong>Confirm Move</strong>. Once it reaches a planet’s hex, <strong>Enter Orbit · [planet]</strong> becomes available. Movement within a system uses no warp fuel. Select <strong class="help-check">Move Ships</strong> to show the ship selector and click a hex for direct GM placement, or drag a ship. This mode does not open the planet editor. In orbit, Move Ships also allows moving the orbiting marker.</p>`:
        `<h3>Enter and explore a system</h3><p>At your ship’s current star, choose <strong class="help-check">Enter Star System</strong>. Select your ship, click a destination hex, and press <strong>Confirm Move</strong>. A crew member operating the ship must be stationed at its working Bridge. Movement within a system uses no warp fuel.</p><p>When the ship reaches a planet’s hex, use <strong>Enter Orbit · [planet]</strong>. In orbit, <strong>Leave Orbit</strong> returns the ship to the system view. Page 5 explains descent and departure.</p><h3>Revisit known planets</h3><p><strong class="help-check">Browse Planets</strong> lists available destinations. For visited planets, it includes the planet graphic, the GM’s public planet description, and <strong>Preview Surface</strong>, a small surface-map preview.</p><p class="help-reminder">A preview does not land the ship or reveal GM-only notes. Unvisited planets do not receive the same visited-planet preview controls.</p>`,gm?'campaign-system':'campaign-planets','Star Systems'],
      [gm?'Planetary and Regional Maps — Explore and Edit':'Planetary and Regional Maps — Explore Locations',gm?
        `<h3>Shape the surface</h3><p>Use <strong class="help-check">Paint Terrain</strong>, choose a terrain type, and paint hexes. The <strong>city</strong> brush adds settlement markers; <strong>Erase City</strong> removes them. <strong>Undo Stroke</strong> reverses the last paint stroke or whole-map fill. With Temperate, Desert, Ice, Volcanic, Ocean, or Moon selected, <strong class="help-check">Apply to all</strong> asks for confirmation before repainting every hex in the current planet or region. Cities, regions, descriptions, and attachments remain intact. City brushes do not offer Apply to all. Return to <strong>Pan Map</strong> to drag the view.</p><h3>Describe a location</h3><p>Select <strong class="help-check">Edit Locations</strong>, choose a hex, then <strong>Edit Location Details</strong> to set its label, public description, GM-only information, and attachments. <strong>Read Location Details</strong> opens the full description.</p><h3>Add a closer map</h3><p>On a planetary hex without a region, <strong>Create Region</strong> creates its regional map. <strong>Enlarge Region · [name]</strong> opens an existing region. Creating or viewing a region does not move the party into it.</p><p><strong class="help-check">Move Markers</strong> lets you drag the party marker; <strong>Move Party Here</strong> relocates it to the selected hex. Parked ships keep their own locations.</p><p>Planet surfaces have fixed edges and do not wrap. <strong>Fit Map</strong> zooms out until the full height is visible. On narrow screens, pan horizontally to reach the far side. Regions retain their normal framing and can zoom out farther.</p>`:
        `<h3>Inspect a hex</h3><p>Click a hex to select it, then <strong class="help-check">Read Location Details</strong> for its public description. City markers and named locations help identify places of interest.</p><p>Selecting a hex does not move the party. On the party’s current map, <strong>Travel Here</strong> sends a request to the GM. Page 5 explains approval and arrival.</p><h3>Open a regional map</h3><p>A region is a closer map associated with one planetary hex. <strong>View Region · [name]</strong> becomes available when the GM has brought the party into that region. Use the location bar to return to an available broader view.</p><h3>Move the view</h3><p>Drag to pan and scroll or press <strong>+ / −</strong> to zoom. Planet surfaces have fixed edges and do not wrap. <strong>Fit Map</strong> shows the full height; on narrow screens, pan horizontally to see the far side. For regions, it restores the normal framing.</p><p class="help-reminder">The party pin and parked ship are separate. Reading a location or panning the map does not bring your party aboard a ship.</p>`,gm?'campaign-terrain':null,'Surface & Region'],
      ['Travel — Journeys, Landing, and Boarding',gm?
        `<h3>Between stars</h3><p>Select a destination star and ship, then <strong class="help-check">Ship &amp; travel → Review Journey</strong>. Review the drive, distance, timing, and fuel before <strong>Enter Warp</strong>. Suggested fuel is preselected. A partial-journey warning must be acknowledged; the ship will stop short of its destination. Players must be assigned to the ship and stationed at its working Bridge to initiate warp.</p><h3>Approve surface travel</h3><p>Players select a hex and press <strong>Travel Here</strong>. Open the <strong>envelope beside Help</strong>, then <strong>Approve Travel</strong> or <strong>Decline Travel</strong>. Approval starts a shared, timed journey. Select <strong>Move Markers</strong> to use <strong>Move Party Here</strong> for direct relocation.</p><h3>Land and return</h3><p>In orbit, a powered, working ship with landing gear and Hover Generators or Aerofoil can <strong>Descend</strong>. Players need <strong class="help-check">a character stationed at the Bridge</strong>. After descent, its initiator or the GM selects a hex and presses <strong>Land Here</strong>.</p><p>Reaching a parked PC ship’s location places the party aboard near its airlock. Open <strong>Starships</strong> to move and staff the Bridge; use <strong>Leave Atmosphere</strong> to return to orbit.</p><p>A working Transporter offers <strong>Beam Down to Planet’s Surface</strong> and eligible passengers can <strong>Beam Aboard</strong>. Follow its operator, passenger, shield, and safety prompts; see the Starships console for detailed operation.</p>`:
        `<h3>Travel between stars</h3><p>Select your ship and destination, then open <strong class="help-check">Ship &amp; travel → Review Journey</strong>. You must belong to the ship’s crew and be stationed at its working Bridge to initiate warp. Review distance, timing, and selected fuel before pressing <strong>Enter Warp</strong>.</p><p class="help-warning">If fuel covers only part of the route, acknowledge the warning to depart. The ship will stop between stars, short of the destination.</p><h3>Land on a planet</h3><p>Reach its system hex, <strong>Enter Orbit</strong>, then <strong>Descend</strong>. The ship needs working landing equipment and <strong class="help-check">a character stationed at the Bridge</strong>. After descent, the player who began it or the GM selects a hex and presses <strong>Land Here</strong>.</p><h3>Travel on foot and return aboard</h3><p>Choose a hex on the party’s current map and press <strong>Travel Here</strong>. The GM approves or declines; decisions arrive in the <strong>envelope beside Help</strong>. Approval starts a shared journey.</p><p>Reaching a parked PC ship’s location places the party aboard near its airlock. Open <strong>Starships</strong>, move to a working Bridge station, then use <strong>Leave Atmosphere</strong> when the ship can launch.</p><p>Transporter travel is an alternative when available. Follow the <strong>Beam Down to Planet’s Surface</strong> / <strong>Beam Aboard</strong> prompts; passenger location, crew, shields, and working equipment matter.</p>`,null,'Travel'],
      ['Locations, Discoveries, and Shops',gm?
        `<h3>Public information and secrets</h3><p>In <strong class="help-check">Edit Location Details</strong>, put player-facing lore in <strong>Public description</strong>. Keep secrets in <strong>GM-only information</strong>. Players receive the public information, not your private notes or file attachments.</p><h3>Attach prepared content</h3><p>Attach an <strong>NPC roster</strong>, <strong>Surface encounter</strong>, or <strong>Story Console</strong> file to a hex. Its <strong>Load Ally NPCs</strong>, <strong>Load Encounter</strong>, or <strong>Load Story Console</strong> button appears when that hex is selected.</p><p class="help-reminder">Arrival does not load these files. Press the relevant Load button when ready. Loading a location’s Story Console opens Script and adds new chapter tabs, preserving the current chapters.</p><h3>Open a location’s shop</h3><p>Select an <strong>Arrival shop</strong> or attach a saved Shop file. On arrival, confirm <strong>Open Shop</strong> to make it available to players. They buy through the normal <strong>Shop</strong> tab; see its Help for purchasing details.</p><h3>Choose the starting location</h3><p class="help-warning"><strong>In Move Markers mode, Start Campaign Here saves this starting point AND moves the party here now.</strong> Players remain on the surface until departure or GM changes. Use <strong>Move Party Here</strong> for relocation without replacing the saved starting point.</p>`:
        `<h3>Read what the party discovers</h3><p>Select a location and use <strong class="help-check">Read Location Details</strong> for its public description. A planet’s general public description and surface preview are also available under <strong>Browse Planets</strong> after it has been visited.</p><p>Your GM may reveal additional clues through narration or Private Notes. The <strong>envelope beside Help</strong> shows private messages and notices; use it to reply to your GM. A <strong>Receive Reward</strong> button applies an offered resource reward once.</p><h3>Visit a shop</h3><p>Some locations have an associated shop. Reaching the location prompts the GM to make it available. Open the <strong class="help-check">Shop</strong> tab to browse available equipment and purchase it. See Shop Help for departments, prices, and purchasing.</p><h3>When a view is unavailable</h3><p>A campaign can begin on a planet or inside a region. Broader map views may remain unavailable until the party departs or the GM changes access. Ask your GM about the next destination; inspecting maps does not relocate the party.</p>`,gm?'campaign-location-editor':null,'Locations & Shops']
    ],
    characters:gm?[
  [
    "Characters — Manage Your Cast",
    "<p>The <strong class=\"help-check\">Characters</strong> tab brings together your campaign’s Player Characters, allied NPCs, and reusable <strong class=\"help-check\">Premade NPCs</strong>.</p><p>Use the roster to check connection status, inspect sheets, and award class-specific rewards. Cards use each character’s identifying ATB color, with their icon beside their name.</p><h3>Player Characters</h3><p>Players create or import their PCs; the GM can also import saved roster data. An <strong>Offline</strong> PC remains in the campaign.</p><h3>Non-Player Characters</h3><p>NPCs use two Attributes and two Skills instead of a full PC sheet. They can represent allies, enemies, or neutral characters. Allied NPCs appear alongside the PCs; reusable configurations are managed in <strong>Premade NPCs</strong> below the roster.</p><p>The following pages cover roster controls, NPC dice, creating encounter templates, and roster files and the Drama Deck.</p>",
    "characters-overview",
    "Overview"
  ],
  [
    "Player Characters and the Roster",
    "<h3>Read a PC card</h3><p><strong>Character / Player name</strong> identifies both people; <strong>Connected / Offline</strong> shows the player’s connection. <strong class=\"help-check\">Speed</strong> is ATB Speed. <strong>Command</strong> is the Command Window in seconds. <strong>Notes Read</strong> counts read private notes out of those received.</p><p><strong>Character Password</strong> lets the GM help a player regain access. <span class=\"help-warning\">Keep it private.</span></p><h3>Open a sheet</h3><p>Click <strong class=\"help-check\">View Sheet</strong> to inspect Attributes, Skills, equipment and resources. Use <strong>Close Sheet</strong> to return to the roster. For administrative edits, open <strong>GM Settings → Adjust Character</strong>.</p><p>An <strong>Ally NPC</strong> card shows Speed, current / maximum HP, Move and its assigned PC ship, if any. Its <strong>View Sheet</strong> opens a simplified, read-only NPC summary. Assign NPC crew in <strong>Starships</strong>.</p><h3>Class-specific rewards</h3><p>Only the relevant class displays its reward button. Confirm the in-game condition before using it.</p><ul><li><strong>Playboy / Minx — +1 REV / +5 XP:</strong> award 1 Reverence (up to its cap) and 5 XP when its class condition is met.</li><li><strong>Psychopath — +8 XP KILL:</strong> award 8 XP for a qualifying kill; at most three awards per session.</li><li><strong>Peacekeeper — PREVENTED COMBAT: +1 DRAMA:</strong> award one Drama Card; at most two awards per session.</li></ul>",
    "characters-roster",
    "Roster & Sheets"
  ],
  [
    "NPCs — Same Dice, Fewer Stats",
    "<p><strong class=\"help-check\">Physical Attribute</strong> represents physical capability; <strong class=\"help-check\">Mental Attribute</strong> represents mental capability. Their ratings run from <strong>2–20</strong>. <strong>Physical Skill</strong> and <strong>Mental Skill</strong> run from <strong>0–4</strong> and represent training.</p><h3>Turn a rating into dice</h3><p>The Attribute number is a rating, not a number of dice or a flat roll bonus. Ratings 2–4 give that many D4s. Each rating above 4 upgrades one die, cycling through the four dice from D4 to D6, D8, D10 and D12.</p><p class=\"help-reminder\"><strong>Example:</strong> Attribute 8 gives <strong>4D6</strong>. Attribute 9 gives <strong>1D8 + 3D6</strong>. For an Attribute + Skill check, fuse matching results normally, keep the highest two resulting values, then add the applicable Skill and modifiers. Damage rolls add all their dice without fusion.</p><h3>Use the relevant pair</h3><p>Physical stats cover supported physical checks such as attacks and dodging; Mental stats cover supported mental checks such as perception or resisting distress. Combat applies the modifiers relevant to the chosen action, including weapon and range effects where applicable.</p><h3>Outside combat</h3><p>You can roll real dice for NPC actions and resolve them using the normal rules. This is a tabletop workflow; the NPC editor is not a general-purpose roll button. If an action needs a more specific capability, such as Charisma, choose an appropriate pool, Skill and Difficulty for the NPC and circumstances.</p><p><strong>These simplified stats do not prevent NPCs from attempting other actions or make them inherently weaker than PCs.</strong></p>",
    "characters-stats",
    "NPC Dice"
  ],
  [
    "Premade NPCs and Encounters",
    "<p>Use <strong class=\"help-check\">New NPC</strong> to create a reusable configuration. Set its name, Physical / Mental Attributes and Skills, <strong>Held Weapon</strong>, identifying <strong>Color</strong>, and <strong>Ally</strong> status.</p><h3>Calculated values and overrides</h3><p>For a new NPC, <strong>ATB Speed</strong> is Mental Attribute + Mental Skill. <strong>Move</strong> is base 2 + Physical Skill + one for each D10/D12 in its Physical dice pool. <strong>HP</strong> is the maximum total of its Physical dice + 20.</p><p class=\"help-reminder\">You can edit any of these three values manually. That field becomes <strong>Manual</strong> and keeps your value when other stats change. <strong>Recalculate</strong> restores all three calculated values. Existing presets retain their configured values until you recalculate.</p><h3>Choose an icon</h3><p>Click <strong class=\"help-check\">Icon</strong>, select an <strong>Appearance</strong>, then click a variant. Every available character appearance is offered. <strong>Choosing an icon does not apply racial abilities or change statistics.</strong></p><h3>Save and reuse</h3><p>Click <strong>Save Premade NPC</strong>. Select it later in the Premade NPC list and use <strong>Update Premade NPC</strong> to save edits, or <strong>Delete</strong> to remove the template. <span class=\"help-warning\">Updating or deleting a template does not rewrite or remove existing deployed NPCs.</span></p><p>In <strong>Prepare Combat → Add NPC</strong>, select the template, adjust that copy, and press <strong>Add</strong>. You can choose an icon before adding it or change its <strong>Icon</strong> in the added NPC list. Review starting positions before <strong>Begin Combat</strong>.</p><p>Allies use the same simplified statistics. Marking an NPC as <strong>Ally</strong> identifies its allegiance; assign its starship crew separately in <strong>Starships</strong>.</p>",
    "characters-prepare",
    "Create & Reuse"
  ],
  [
    "Character Files and the Drama Deck",
    "<h3>Roster files</h3><p><strong class=\"help-check\">Save</strong> downloads <strong>Character Roster.sa2roster</strong> with the campaign’s PC character data and NPC configurations. <strong>Save Selected NPCs</strong> lets you select individual premade templates, then use <strong>Save NPC Roster</strong> to export just those NPCs.</p><p><strong>Load</strong> opens a review before adding saved characters and NPCs to this campaign. It does not replace the current roster. Imported PCs receive new character passwords. A previously loaded file offers <strong>Open current content</strong> or <strong>Load New Copy</strong>; creating a new copy deliberately adds separate characters.</p><p class=\"help-warning\">A roster file is not a full campaign backup. It does not restore crew assignments, private-note history or the shared Drama Deck. Review imported characters and assign crew in <strong>Starships</strong>. Use <strong>Save Campaign</strong> for a full campaign backup.</p><h3>Inspect the Drama Deck</h3><p>Click the <strong class=\"help-check\">Drama Deck</strong> badge to open its dialog. <strong>Draw</strong> counts cards remaining in the draw pile; <strong>Discard</strong> counts cards currently in the discard pile. Click a discarded card to read its full text.</p><p><strong>Reshuffle</strong> returns discarded cards to the draw pile. It is unavailable when there are no discarded cards. <strong>Close</strong> returns you to the same place in Characters. The same discard controls are also available under <strong>Prompt / Give → Campaign Tools → Drama Card Discard Pile</strong>.</p><p>Class-specific reward buttons are explained on <strong>Roster &amp; Sheets</strong>.</p>",
    "characters-deck",
    "Files & Drama"
  ]
]:[['Characters',"Your Character Sheet holds identity, attributes, skills, health, equipment, and advancement. During creation, follow Next Step, spend your starting points, and finish with Finalize. Purchased equipment is managed under Supplies; use the Shop to buy more.",'Identity  →  Attributes & Skills  →  Supplies']],
    starships:[['Starships and crew','Choose a ship to see its sheet and interior map. Crew assignments say who belongs to a ship; the map shows where they actually are. Select a destination to move, then confirm the route. Move onto a station and use Console View to operate it. Combat View returns to the encounter. Drag empty map space to reposition the view.','Ship  →  Crew  →  Station  →  Console'],['Building and resources',gm?'Create or load ships here, then assign PCs or NPCs as crew. In construction, purchase SICs, place them on legal hull cells, and confirm your changes. A SIC in Storage is owned but not installed. Read card restrictions before placing exterior equipment or adding stations.':'Your GM assigns ship crew. If you can upgrade a ship, purchase and place its equipment in construction, then Confirm Changes. Cancel Upgrade discards that unfinished edit. Fuel, minerals, and installed systems are shown on the ship sheet.'] ],
    prompt:[['Prompt / Give','First select the PCs in Recipients; each box uses that character’s ATB color. Direct Check asks them for an attribute and skill check; the results appear below after they confirm their dice.','Recipients  →  Action  →  Result'],['Awards, time, and records','Give Resources awards the selected resource and amount. Check whether you chose Personal or Group Credits. Recharge Items restores supported carried equipment. Pass Time advances campaign time and timed services outside active combat. Give Minerals selects a destination ship. Library entries become campaign reference material and are included in Save Campaign.']],
    combat:[['Prepare and begin combat',gm?'Choose Surface Combat for characters on an arena, or Starship Combat for ships and their crews. Add combatants, choose their starting locations, and arrange objects. The highlighted map action controls what a click or drag does. Surface preparation has Pan Map, Paint Floor, Add Walls, Add Doors, Erase Boundaries, and Move Characters. Starship preparation separates Move Ships, Reposition Planets, and Reposition Objects. Place on Map highlights the object being placed; Cancel Placement exits that action. Expand Objects on map to edit placed objects. Review the roster before Begin Combat; Engage Clock starts ATB progression.':'Your GM prepares the encounter. Watch your character’s ATB bar; when it fills, choose an available action. Select a target or movement destination and confirm. The clock pauses for requested dice.','Prepare  →  Begin Combat  →  Engage Clock'],['Actions and dice','Movement, attacks, Aim, items, and station controls become available when appropriate. Charges and recovery use active combat time. Roll when prompted, inspect the result, and Confirm and Submit. A displayed result is not sent until confirmed. If you are viewing a console, Combat View returns to the map. The GM can pause the clock and help disconnected players.']],
    shop:[['Shop','Create or load shops here. Edit availability and prices, then enable Available to let players purchase. Private messages and approvals are in the header mail window.']],
    inbox:[['Inbox','Review incoming messages, roll results, and approvals here. Select an entry to see its details. The unread count helps you find new information. Finish a requested action through its own confirmation controls before deleting the message.']],
    settings:[['Settings and campaign files',gm?'Save Campaign downloads a local campaign file containing its characters, ships, scripts, shops, library, maps, and saved encounter state. Keep dated copies before major sessions. Load Campaign restores a saved campaign. Sound and room preferences are managed here.':'Use Settings for sound and character or campaign preferences. Keep your character access code private. Your GM saves the shared campaign. Help is always available from the header and opens only when you press it.']],
    story:[
  [
    "Script: Prepare Your Story, Run Your Game",
    "<p>The Script tab is where the GM prepares story content, organizes scenes, and manages events during a game session.</p><p>The <strong>Story Console</strong> is your main workspace. Write descriptions, dialogue, GM notes, and anything else you want to reference during play. Organize your story into Chapters to keep different scenes and adventures separate.</p><p>But the Story Console can do more than store text!</p><p>You can insert interactive Checks directly into your script. These appear as clickable checks that the GM can activate whenever the story reaches that moment.</p><p>Instead of manually asking players to roll, you can prepare Checks in advance and trigger them with a click.</p><p>Some scripted Checks can even deliver private messages or rewards to players who succeed.</p><h3>Four Ways to Request Checks</h3><p>The application provides four related tools:</p><p><strong>Direct Check</strong></p><p>Request a check from players immediately in <strong>Prompt / Give</strong>, without preparing anything in advance. <strong>See Prompt/Give Tab for details.</strong></p><p><strong><span class=help-quick>Quick Check</span></strong></p><p>Use a saved check configuration to quickly request a frequently used check. <strong><span class=help-quick>Quick Check</span></strong> stays at the bottom left of the GM interface and also lets you compose and send an unsaved check.</p><p><strong><span class=help-check>Scripted Direct Check</span></strong></p><p>Insert a clickable attribute + skill label into your story that requests a Direct Check when activated.</p><p><strong><span class=help-check>Scripted Reward Check</span></strong></p><p>Insert a clickable keyword into your story that requests a check and can automatically deliver a reward or private message when a player succeeds.</p><p>All four tools request checks from players, but each serves a different purpose.</p><p>The following pages explain how to use the Story Console and its interactive features.</p>",
    "story-overview",
    "Introduction"
  ],
  [
    "Writing and Organizing Your Story",
    "<p>The Story Console is a text editor where you prepare the material you&#x27;ll use to run your game.</p><p>Write scene descriptions, dialogue, encounters, clues, and notes just as you would in a traditional GM notebook.</p><p>Use <strong>Chapters</strong> to divide your script into manageable sections. You might create a chapter for each location, encounter, or major event.</p><h3>Bringing Your Script to Life</h3><p>Unlike an ordinary text editor, the Story Console supports interactive Checks.</p><p>For example, you might write:</p><p><em>The crew discovers a sealed container buried beneath the wreckage.</em></p><p><em>Anyone examining the container may notice something unusual about its locking mechanism.</em></p><p>You could place a <strong><span class=help-check>Scripted Direct Check</span></strong> immediately after this description.</p><p>When the players investigate the container, click the inserted check label to send the prepared request. A <span class=help-check>Scripted Direct Check</span> shows its Attribute + Skill; a <span class=help-check>Scripted Reward Check</span> shows its saved keyword.</p><p>You can then examine their results and continue narrating the scene.</p><h3><span class=help-check>Scripted Reward Checks</span></h3><p>You can also prepare Checks that automatically deliver special outcomes when successful.</p><p>For example, a successful check might reveal secret information to a particular player or award a resource.</p><p>These are called <strong><span class=help-check>Scripted Reward Checks</span></strong>.</p><p>They work similarly to <span class=help-check>Scripted Direct Checks</span>, but include a configured success effect.</p><h3>Saving Your Work</h3><p><strong>Quick Save</strong> stores your changes in the current campaign.</p><p><strong>Save</strong> downloads a portable copy of your Story Console content.</p><p><strong>Load</strong> lets you import previously saved story content, replacing the current chapters after confirmation. Loading a Story Console attached to a map location opens new chapters and preserves your current work.</p><p>Your script is intended to help you run the game, not force events to happen in a particular order.</p><p>Players are free to make their own decisions, and you can activate prepared Checks whenever they become relevant.</p>",
    "story-console",
    "Story Console"
  ],
  [
    "Creating Checks With Automatic Outcomes",
    "<p><span class=help-check>Scripted Reward Checks</span> allow you to prepare checks that deliver special outcomes when players succeed.</p><p>These Checks are created using the existing conditional check configuration tools and inserted into the Story Console as clickable keywords.</p><p>Each <span class=help-check>Scripted Reward Check</span> has a keyword, roll requirements, and a configured success effect.</p><h3>Example: A Hidden Supply Cache</h3><p>Imagine the players are searching an abandoned research facility.</p><p>You want characters who succeed at a Perception + Awareness check to discover a hidden supply cache.</p><p>To create this <span class=help-check>Scripted Reward Check</span>:</p><ol><li>Enter a keyword, such as <strong>FIND CACHE</strong>.</li><li>Choose the required Attribute and Skill.</li><li>Set the Difficulty.</li><li>Choose the outcome that occurs when the check succeeds.</li><li>Save the configuration.</li></ol><p>For this example, you could select <strong>Private Message</strong> and enter:</p><p><em>You notice scratches along the floor. Behind a loose wall panel, you discover a concealed supply cache.</em></p><p>When a player successfully completes the check, the application can deliver that information privately.</p><p>Alternatively, you can configure a reward that is sent to the player’s inbox upon success.</p><h3>Adding the Check to Your Script</h3><p>After saving the configuration, select its <strong><span class=help-check>Scripted Reward Check</span></strong> entry in <strong>Insert Scripted Check</strong>, then press <strong>Insert Check</strong> at the story cursor.</p><p>The keyword becomes clickable.</p><p>When the players reach that moment in the story, click it to send the prepared check request.</p><p>After the player successfully completes and confirms the check, a private message arrives automatically. A resource reward is sent to the inbox; the player clicks <strong>Receive Reward</strong> to apply it once.</p><h3>What Makes It Different?</h3><p>A <strong><span class=help-check>Scripted Direct Check</span></strong> simply requests a check from the script.</p><p>A <strong><span class=help-check>Scripted Reward Check</span></strong> requests a check and includes an automatic success effect.</p><p>Both are activated through clickable checks in the Story Console. Direct checks show their Attribute + Skill; reward checks show the keyword you saved.</p><p class=help-warning><strong>Important:</strong> Typing a keyword as ordinary text does not automatically create an interactive Check. Use the application&#x27;s insertion tool to create the clickable command.</p><p>The <strong>Send to Story Recipient</strong> button also lets you send a configured reward check immediately without inserting it first. It uses the same recipients and success effect.</p>",
    "story-keywords",
    "Scripted Reward Checks"
  ],
  [
    "Choosing the Right Check",
    "<p>All four Check types allow the GM to request rolls from players.</p><p>The difference is how they are prepared, activated, and resolved.</p><h3>Direct Check — Request a Check Immediately</h3><p>Use a Direct Check when a player attempts something unexpected or you need an immediate roll.</p><p>Choose the Attribute, Skill, Difficulty if applicable, and recipients, then send the request.</p><p>Open <strong>Prompt / Give</strong> to send it. No script preparation is required. <strong>See Prompt/Give Tab for details.</strong></p><p><strong>Best for:</strong> Spontaneous player actions and unexpected situations.</p><h3><span class=help-quick>Quick Check</span> — Reuse a Saved Check</h3><p><span class=help-quick>Quick Checks</span> are saved check configurations that can be used repeatedly.</p><p>Open <strong><span class=help-quick>Quick Check</span></strong> at the bottom left, select a saved check, and send it. You can also compose and send an unsaved check here.</p><p><strong>Best for:</strong> Frequently requested checks.</p><h3><span class=help-check>Scripted Direct Check</span> — Activate a Check From Your Story</h3><p><span class=help-check>Scripted Direct Checks</span> are prepared checks inserted into the Story Console as clickable attribute + skill labels.</p><p>When the story reaches the appropriate moment, click the inserted check label to request the check.</p><p>They perform the same basic function as Direct Checks, but are activated from the script.</p><p><strong>Best for:</strong> Prepared encounters, planned discoveries, and scripted events that require a roll.</p><h3><span class=help-check>Scripted Reward Check</span> — Activate a Check With a Success Effect</h3><p><span class=help-check>Scripted Reward Checks</span> are also embedded in the Story Console.</p><p>However, they can automatically deliver a configured reward or private message when a player succeeds.</p><p><strong>Best for:</strong> Hidden clues, secret information, conditional rewards, and special discoveries.</p><h3>Quick Reference</h3><table><thead><tr><th>Situation</th><th>Recommended Check</th></tr></thead><tbody><tr><td>A player unexpectedly attempts something difficult</td><td>Direct Check</td></tr><tr><td>You frequently request the same type of check</td><td><span class=help-quick>Quick Check</span></td></tr><tr><td>A prepared story event requires a roll</td><td><span class=help-check>Scripted Direct Check</span></td></tr><tr><td>A successful check should reveal secret information</td><td><span class=help-check>Scripted Reward Check</span></td></tr><tr><td>A successful check should grant a reward</td><td><span class=help-check>Scripted Reward Check</span></td></tr></tbody></table><h3>What Happens When You Request a Check?</h3><p>The selected players receive a check request.</p><p>They roll using the application&#x27;s dice system and submit their results.</p><p>The GM can review those results and determine what happens next.</p><p>For <span class=help-check>Scripted Reward Checks</span>, successful confirmed results can also send the configured private message or inbox reward. Players apply rewards with <strong>Receive Reward</strong>.</p><p class=help-reminder><strong>Remember:</strong></p><p>Direct Checks are immediate.</p><p><span class=help-quick>Quick Checks</span> are reusable.</p><p><span class=help-check>Scripted Direct Checks</span> are embedded in the story.</p><p><span class=help-check>Scripted Reward Checks</span> are embedded in the story and can produce automatic success effects.</p>",
    "story-rolls",
    "Understanding Checks"
  ]
]
  };
  function open(){
    let host=window;try{while(host.parent!==host&&host.parent.document)host=host.parent;}catch{}
    const doc=host.document;
    if(doc.getElementById('sa-app-help'))return;
    const key=gm?document.querySelector('.gm-tabs .active')?.dataset.tab:document.querySelector('[data-character-tab].active')?.dataset.characterTab;
    const topic=({roster:'campaign',sheet:'characters',atb:'combat',give:'prompt',prompts:'prompt',script:'story'})[key]||key||'campaign';
    const content=pages[topic]||pages.campaign;let page=0;
    const dialog=doc.createElement('dialog');dialog.id='sa-app-help';dialog.setAttribute('aria-label','Help');
    dialog.style.cssText='width:min(1000px,94vw);max-height:85vh;box-sizing:border-box;background:#382112;color:#fff1df;border:2px solid #cd843b;border-radius:14px;padding:20px;box-shadow:0 18px 90px #000c;font:15px/1.5 Arial,sans-serif';
    const style=doc.createElement('style');style.textContent='#sa-app-help::backdrop{background:#080401aa;backdrop-filter:blur(8px)}#sa-app-help button{font:inherit;color:#fff1df;background:#633810;border:1px solid #d8944c;border-radius:8px;padding:8px 16px;cursor:pointer}#sa-app-help button:disabled{opacity:.4;cursor:default}#sa-app-help p{margin:8px 0}#sa-app-help .help-check{color:#80ddff;font-weight:700}#sa-app-help .help-quick{color:#ff91cb;font-weight:700}#sa-app-help .help-warning{color:#ffb3a5}#sa-app-help .help-reminder{color:#ffdf77}#sa-app-help h3{font-size:17px;margin:16px 0 6px}#sa-app-help table{width:100%;border-collapse:collapse;font-size:14px}#sa-app-help th,#sa-app-help td{padding:6px 9px;border:1px solid #946138;text-align:left}#sa-app-help nav{display:flex;gap:5px;flex-wrap:wrap;margin-bottom:14px}#sa-app-help nav button{font-size:13px;padding:5px 9px}#sa-app-help nav button[aria-current=page]{background:#96601f;border-color:#ffcf78}';
    dialog.append(style);const heading=doc.createElement('h2'),body=doc.createElement('div'),preview=doc.createElement('div'),footer=doc.createElement('footer');
    heading.style.cssText='margin:0 0 12px;font-size:22px';body.style.minHeight='0';preview.style.cssText='padding:10px;border:1px solid #bd8648;background:#21160f;text-align:center;color:#ffd494';
    footer.style.cssText='display:flex;align-items:center;gap:12px;margin-top:16px;flex-wrap:wrap;position:sticky;bottom:-20px;background:#382112;padding:12px 0;z-index:2';
    const prev=doc.createElement('button'),next=doc.createElement('button'),count=doc.createElement('span'),dismiss=doc.createElement('button');
    prev.textContent='Previous';next.textContent='Next';dismiss.textContent='Dismiss';dismiss.style.marginLeft='auto';
    const renderPreview=label=>{
      preview.replaceChildren();preview.setAttribute('role','img');preview.setAttribute('aria-label',label||'');
      if(/^(story|campaign|characters)-/.test(String(label||''))){
        const shots={
          "characters-overview":{"file": "help-characters-overview.png", "alt": "Characters roster with PCs, an Ally NPC, and the Premade NPC editor", "caption": "PCs and Ally NPCs appear in the roster. Premade NPCs stay beneath it.", "w": 1249, "h": 672, "width": 900, "gutter": 0, "marks": []},
          "characters-roster":{"file": "help-characters-roster.png", "alt": "PC roster card with status, ATB Speed, Command, Notes Read and View Sheet", "caption": "View Sheet opens the PC sheet. Ally NPCs use a simplified summary.", "w": 403, "h": 225, "width": 780, "gutter": 230, "marks": [["Status", 45, 397, 45], ["View Sheet", 205, 397, 205]]},
          "characters-stats":{"file": "help-characters-stats.png", "alt": "NPC editor with Physical and Mental statistics and calculated values", "caption": "Attribute ratings determine dice; Skills add training. Calculated fields can be overridden.", "w": 710, "h": 435, "width": 780, "gutter": 230, "marks": [["Physical stats", 215, 700, 215], ["Mental stats", 295, 700, 295], ["Recalculate", 410, 700, 410]]},
          "characters-prepare":{"file": "help-characters-prepare.png", "alt": "Prepare Combat NPC editor and a staged NPC with its Icon control", "caption": "Select a template, adjust the copy and Add it. The staged NPC also has an Icon button.", "w": 591, "h": 784, "width": 780, "gutter": 230, "marks": [["Select template", 38, 580, 38], ["Add copy", 570, 370, 570], ["Change icon", 704, 580, 704]]},
          "characters-deck":{"file": "help-characters-deck.png", "alt": "Drama Deck dialog with counts, discarded cards, Reshuffle and Close", "caption": "Click a discarded card to read it. Reshuffle returns discards to the draw pile.", "w": 900, "h": 378, "width": 900, "gutter": 230, "marks": [["Reshuffle", 120, 870, 120], ["Read a card", 240, 445, 240]]},
          'story-overview':{file:'help-script-preview.png',alt:'Complete Script tab, including Insert Scripted Check',caption:'A — Story Console · B — Scripted Reward Check · C — Insert Scripted Check',w:1584,h:1178,width:900,gutter:400,marks:[['A · Story Console',200,1540,200],['B · Reward Check',300,520,300],['C · Insert Check',1000,520,1000]]},
          'story-console':{file:'help-script-console.png',alt:'Story Console with recipients, chapter tabs and the clickable Find Cache command',caption:'A — Choose recipients · B — Organize chapters · C — Click the inserted command during play',w:1031,h:360,width:900,marks:[['A · Recipients',65,650,59],['B · Chapters',140,65,117,140],['C · Run check',280,514,280]]},
          'story-keywords':{file:'help-script-keywords.png',alt:'Find Cache reward check with keyword, success effect and Save Reward Check button',caption:'A — Name the keyword · B — Configure its success effect · C — Save Reward Check',w:516,h:644,height:690,width:740,marks:[['A · Keyword',204,504,204],['B · Success effect',277,504,277],['C · Save check',665,90,633,665]]},
          'story-rolls':{file:'help-script-rolls.png',alt:'Insert Scripted Check configured for Perception plus Awareness at difficulty 10, with Insert Check visible',caption:'A — Choose the check type · B — Insert it at the Story Console cursor',w:516,h:430,width:740,marks:[['A · Check type',90,504,90],['B · Insert Check',396,504,396]]},
          'campaign-gm-overview':{file:'help-campaign-gm-overview.png',alt:'GM Galaxy Map with location bar, map options, ship selector and enlargement controls',caption:'GM overview: location hierarchy above the map, with ship and travel controls beneath it.',w:1800,h:1000,width:900,gutter:0,marks:[]},
          'campaign-pc-overview':{file:'help-campaign-pc-overview.png',alt:'Player Galaxy Map with permitted navigation, Find Ship and Ship and travel',caption:'Player overview: available map views and travel controls. The party is still on Harbor in this example.',w:1800,h:1000,width:900,gutter:0,marks:[]},
          'campaign-star-details':{file:'help-campaign-star-details.png',alt:'Selected Haven star with Edit Details, Edit Solar System, View Haven System and Enter Star System',caption:'View Haven System lets the GM browse. Enter Star System uses the selected ship’s current star.',w:620,h:445,width:840,gutter:240,marks:[['Current star',364,584,364]]},
          'campaign-system':{file:'help-campaign-system.png',alt:'Haven System with its planets, Edit Solar System and Browse Planets',caption:'The system view shows orbital destinations. Browse Planets opens the planet directory.',w:1800,h:1000,width:900,gutter:0,marks:[]},
          'campaign-planets':{file:'help-campaign-planets.png',alt:'Player planet directory with Harbor artwork and Preview Surface; unvisited planets have name buttons',caption:'Visited Harbor has a graphic and a surface preview. Its public description has not yet been written in this example.',w:620,h:456,width:850,gutter:230,marks:[['Surface preview',302,587,302]]},
          'campaign-terrain':{file:'help-campaign-terrain.png',alt:'Paint Terrain mode with six terrain types, city brushes, Undo Stroke and Apply to all at the far right',caption:'Paint Terrain changes terrain. Apply to all confirms a whole-map fill and preserves locations. Edit Locations and Move Markers are separate modes.',w:1800,h:1000,height:145,cropTop:198,width:900,gutter:250,marks:[['Apply to all',62,1750,62],['Brushes',115,390,62]]},
          'campaign-location-editor':{file:'help-campaign-location-editor.png',alt:'Location editor showing separate public description, GM-only information and Arrival shop fields',caption:'Players receive the public description. GM-only information remains private; Arrival shop is a separate setting.',w:584,h:338,width:820,gutter:236,marks:[['Public description',77,575,77],['GM only',209,575,209],['Arrival shop',312,575,312]]}
        },shot=shots[label],gutter=shot.gutter??224,totalWidth=shot.w+gutter,totalHeight=shot.height||shot.h;
        preview.setAttribute('aria-label',shot.alt+'. '+shot.caption);
        const figure=doc.createElement('figure');figure.style.cssText='margin:0 auto;max-width:'+shot.width+'px';
        const frame=doc.createElement('div');frame.style.cssText='position:relative;aspect-ratio:'+totalWidth+'/'+totalHeight;
        const image=doc.createElement('img');image.src=new URL(shot.file+'?v='+(label.startsWith('story-')?'20261017-arrows':label.startsWith('characters-')?'20261018-characters':'20261018-map-controls'),location.href).href;image.alt=shot.alt;image.style.cssText='display:block;width:'+shot.w/totalWidth*100+'%;height:auto;border:1px solid #aa8050;box-sizing:border-box';if(shot.cropTop){frame.style.overflow='hidden';image.style.transform='translateY(-'+shot.cropTop/shot.h*100+'%)';}frame.append(image);
        const ns='http://www.w3.org/2000/svg',overlay=doc.createElementNS(ns,'svg'),arrowId='help-arrow-'+label;
        overlay.setAttribute('viewBox',`0 0 ${totalWidth} ${totalHeight}`);overlay.setAttribute('aria-hidden','true');overlay.style.cssText='position:absolute;inset:0;width:100%;height:100%;pointer-events:none';
        overlay.innerHTML=`<defs><marker id="${arrowId}" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="8" markerHeight="8" orient="auto-start-reverse"><path d="M0 0L10 5L0 10Z" fill="#ffd474"/></marker></defs>`;
        for(const [text,y,tx,ty,routeY]of shot.marks){
          const line=doc.createElementNS(ns,'path'),start=shot.w+10;
          line.setAttribute('d',routeY==null?`M${start} ${y}L${tx} ${ty}`:`M${start} ${y}V${routeY}H${tx}V${ty}`);line.setAttribute('fill','none');line.setAttribute('stroke','#ffd474');line.setAttribute('stroke-width',shot.w>1400?'3':'2');line.setAttribute('marker-end',`url(#${arrowId})`);line.style.filter='drop-shadow(0 1px 2px #000)';
          const label=doc.createElementNS(ns,'text');label.setAttribute('x',shot.w+22);label.setAttribute('y',y+7);label.setAttribute('fill','#ffdc8b');label.setAttribute('font-size',shot.w>1400?'30':'20');label.setAttribute('font-family','Arial, sans-serif');label.setAttribute('font-weight','700');label.textContent=text;overlay.append(line,label);
        }
        frame.append(overlay);
        const caption=doc.createElement('figcaption');caption.textContent=shot.caption;caption.style.cssText='font-size:13px;line-height:1.5;margin-top:8px';figure.append(frame,caption);preview.append(figure);
      }else if(/Select star/.test(label||'')){
        const svg=doc.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('viewBox','0 0 520 70');svg.style.cssText='width:100%;max-height:75px';
        for(const [tag,attributes] of [['path',{d:'M70 35L430 35',stroke:'#67dfff','stroke-width':2,'stroke-dasharray':'7 6'}],['circle',{cx:70,cy:35,r:18,fill:'#ffd361'}],['circle',{cx:430,cy:35,r:12,fill:'#f5a444'}],['path',{d:'M246 24L267 35L246 46L251 35Z',fill:'#73e7ff'}]]){const node=doc.createElementNS(svg.namespaceURI,tag);for(const [key,value] of Object.entries(attributes))node.setAttribute(key,String(value));svg.append(node);}preview.append(svg);
      }else for(const [i,text] of String(label||'').split(/\s*(?:→|\||·)\s*/).entries()){
        const chip=doc.createElement('span');chip.textContent=text;chip.style.cssText='display:inline-block;margin:4px;padding:8px 12px;border:1px solid '+['#63d7f1','#ffcd6b','#aef0bc'][i%3]+';border-radius:6px;background:#17242a;font-size:14px';preview.append(chip);
      }
    };
    const tabs=doc.createElement('nav');tabs.setAttribute('aria-label','Help pages');if((['story','campaign'].includes(topic)||(gm&&topic==='characters')))content.forEach((item,index)=>{const tab=doc.createElement('button');tab.textContent=item[3];tab.onclick=()=>{page=index;render();};tabs.append(tab);});
    const render=()=>{heading.textContent=content[page][0];if((['story','campaign'].includes(topic)||(gm&&topic==='characters')))body.innerHTML=content[page][1];else body.textContent=content[page][1];for(const [index,tab]of [...tabs.children].entries()){if(index===page)tab.setAttribute('aria-current','page');else tab.removeAttribute('aria-current');}renderPreview(content[page][2]);preview.hidden=!content[page][2];prev.hidden=next.hidden=count.hidden=content.length===1;prev.disabled=page===0;next.disabled=page===content.length-1;count.textContent=`${page+1} / ${content.length}`;dialog.scrollTop=0;};
    prev.onclick=()=>{page--;render();};next.onclick=()=>{page++;render();};dismiss.onclick=()=>dialog.close();
    footer.append(prev,count,next,dismiss);dialog.append(tabs,heading,body,preview,footer);doc.body.append(dialog);
    dialog.onclose=()=>{dialog.remove();button.focus();};window.addEventListener('pagehide',()=>dialog.remove(),{once:true});render();dialog.showModal();dismiss.focus();
  }
  const anchor=document.getElementById(gm?'gmMailButton':'pcHeaderMail');if(!anchor)return;
  const button=document.createElement('button');button.type='button';button.id='appHelp';button.textContent='Help';button.onclick=open;anchor.before(button);
})();
